namespace NotificationsApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 4;

    private readonly List<NotificationItem> _notifications =
    [
        new() { Id = 1, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
        new() { Id = 2, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
        new() { Id = 3, Message = "New feature: dark mode is available.", Timestamp = DateTime.UtcNow.AddMinutes(-1) },
    ];

    private static readonly string[] SampleMessages =
    [
        "Deployment completed successfully.",
        "A new user signed up.",
        "Disk usage exceeded 80%.",
        "Backup finished.",
        "Security scan passed.",
        "New comment on your post.",
        "Server restarted.",
    ];

    public Task<List<NotificationItem>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.OrderByDescending(n => n.Timestamp).ToList());
        }
    }

    /// <summary>
    /// Returns any notifications newer than the given timestamp.
    /// Randomly generates 0–1 new notifications per call to simulate activity.
    /// </summary>
    public Task<List<NotificationItem>> GetNotificationsSinceAsync(DateTime since)
    {
        lock (_notifications)
        {
            if (Random.Shared.Next(3) == 0) // ~33% chance of a new notification
            {
                _notifications.Add(new NotificationItem
                {
                    Id = _nextId++,
                    Message = SampleMessages[Random.Shared.Next(SampleMessages.Length)],
                    Timestamp = DateTime.UtcNow,
                });
            }

            return Task.FromResult(
                _notifications
                    .Where(n => n.Timestamp > since)
                    .OrderByDescending(n => n.Timestamp)
                    .ToList());
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationSvc
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading notifications...</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="notification-list">
        @foreach (var n in notifications)
        {
            <li>
                <strong>@n.Message</strong>
                <small>@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<NotificationItem>? notifications { get; set; }

    private CancellationTokenSource? _cts;
    private DateTime _lastCheck;

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we don't re-fetch data that was persisted from prerender
        notifications ??= await NotificationSvc.GetNotificationsAsync();
        _lastCheck = notifications.FirstOrDefault()?.Timestamp ?? DateTime.UtcNow;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                var newer = await NotificationSvc.GetNotificationsSinceAsync(_lastCheck);
                if (newer.Count > 0)
                {
                    notifications = [..newer, ..notifications!];
                    _lastCheck = notifications.First().Timestamp;
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
        }
    }
}

